import threading


class Ledger:
    """Account balances. All mutation must hold self._lock (accessed from worker threads)."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._balances: dict[str, int] = {}

    def deposit(self, account: str, amount: int) -> None:
        with self._lock:
            self._balances[account] = self._balances.get(account, 0) + amount

    def withdraw(self, account: str, amount: int) -> None:
        with self._lock:
            if self._balances.get(account, 0) < amount:
                raise ValueError("insufficient funds")
            self._balances[account] -= amount

    def balance(self, account: str) -> int:
        with self._lock:
            return self._balances.get(account, 0)

    def apply_refund(self, account: str, amount: int) -> None:
        current = self._balances.get(account, 0)
        self._balances[account] = current + amount
